function checkQty(qty) {
  if (!Number.isFinite(qty) || qty <= 0) throw new Error("Quantity must be more than 0");
}

function matches(item, name) {
  return item.name.toLowerCase() === name.trim().toLowerCase();
}

function receive(stock, name, qty) {
  checkQty(qty);
  if (stock.some((i) => matches(i, name))) {
    return stock.map((i) => (matches(i, name) ? { ...i, qty: i.qty + qty } : i));
  }
  return [...stock, { name: name.trim(), qty }];
}

function dispense(stock, name, qty) {
  checkQty(qty);
  const item = stock.find((i) => matches(i, name));
  if (!item || item.qty < qty) throw new Error(`Not enough ${name.trim()}`);
  return stock.map((i) => (i === item ? { ...i, qty: i.qty - qty } : i));
}

