var Chama = (function () {
  const members = new Map();     // private: name -> total paid

  function join(name) {
    const clean = String(name).trim();
    if (clean === "" || members.has(clean)) return false;
    members.set(clean, 0);
    return true;
  }

  function pay(name, amount) {
    if (!members.has(name)) throw new Error(`${name} is not a member`);
    if (typeof amount !== "number" || !Number.isFinite(amount) || amount <= 0) throw new Error("Amount must be more than 0");
    members.set(name, members.get(name) + amount);
    return members.get(name);
  }

  function balanceOf(name) {
    return members.get(name) || 0;
  }

  function total() {
    return [...members.values()].reduce((sum, v) => sum + v, 0);
  }

  function names() {
    return [...members.keys()].sort((a, b) => a.localeCompare(b));
  }

  return { join, pay, balanceOf, total, names };   // the only way in
})();

