// Clinic queue: adds names to the list and announces the change.
const queue = [];
const form = document.getElementById("add-form");
form.addEventListener("submit", (event) => {
  event.preventDefault();
  const box = document.getElementById("patient");
  const name = box.value.trim();
  if (name === "") return;
  queue.push(name);
  const li = document.createElement("li");
  li.textContent = name;
  document.getElementById("queue").appendChild(li);
  document.getElementById("status").textContent = `${name} added. ${queue.length} waiting.`;
  box.value = "";
  box.focus();
});
